function(container, apiUrl, tables) {
  // エラー情報の初期化（URLパラメータやlocalStorageから取得可能）
  const errorInfo = {
    title: "システムエラーが発生しました",
    message: "予期しないエラーが発生しました。しばらく時間をおいて再度お試しください。",
    code: "ERR_500_INTERNAL",
    timestamp: new Date().toLocaleString('ja-JP'),
    solution: "1. ページを再読み込みしてください\n2. 問題が続く場合は管理者にお問い合わせください\n3. 緊急の場合は直接お電話でご連絡ください"
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      Object.assign(errorInfo, errorData);
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  container.querySelector('#error-title').textContent = errorInfo.title;
  container.querySelector('#error-message').textContent = errorInfo.message;
  container.querySelector('#error-code').textContent = errorInfo.code;
  container.querySelector('#error-timestamp').textContent = errorInfo.timestamp;
  container.querySelector('#error-solution').innerHTML = errorInfo.solution.replace(/\n/g, '<br>');

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', () => {
    // 前の画面に戻って再実行
    if (window.history.length > 1) {
      window.history.back();
      setTimeout(() => {
        window.location.reload();
      }, 100);
    } else {
      window.location.reload();
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（ホーム画面として）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact').addEventListener('click', () => {
    // 緊急報告画面に遷移してエラー情報を引き継ぐ
    const errorData = encodeURIComponent(JSON.stringify({
      type: 'system_error',
      title: errorInfo.title,
      message: errorInfo.message,
      code: errorInfo.code,
      timestamp: errorInfo.timestamp,
      url: window.location.href,
      userAgent: navigator.userAgent
    }));
    window.showScreen('scr-1778907330826', { error: errorData }); // 緊急報告画面
  });

  // エラー詳細表示切り替え
  container.querySelector('#btn-toggle-details').addEventListener('click', () => {
    const detailsDiv = container.querySelector('#error-details');
    const toggleBtn = container.querySelector('#btn-toggle-details');

    if (detailsDiv.classList.contains('hidden')) {
      detailsDiv.classList.remove('hidden');
      toggleBtn.textContent = 'エラー詳細を非表示';
    } else {
      detailsDiv.classList.add('hidden');
      toggleBtn.textContent = 'エラー詳細を表示';
    }
  });

  // キーボードショートカット
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      // ESCキーでホームに戻る
      window.showScreen('scr-1778907133295');
    } else if (e.key === 'F5' || (e.ctrlKey && e.key === 'r')) {
      // F5またはCtrl+Rで再試行
      e.preventDefault();
      container.querySelector('#btn-retry').click();
    }
  });

  // 自動リロード機能（30秒後）
  let autoReloadTimer = setTimeout(() => {
    if (confirm('30秒が経過しました。自動的に再試行しますか？')) {
      container.querySelector('#btn-retry').click();
    }
  }, 30000);

  // 画面を離れる時にタイマーをクリア
  const cleanup = () => {
    if (autoReloadTimer) {
      clearTimeout(autoReloadTimer);
      autoReloadTimer = null;
    }
  };

  // クリーンアップ関数を登録
  if (container.cleanup) {
    const originalCleanup = container.cleanup;
    container.cleanup = () => {
      cleanup();
      originalCleanup();
    };
  } else {
    container.cleanup = cleanup;
  }
}
